<template>
  <view class="netops-page audit-page">
    <view class="audit-hero"><view><text>SYSTEM AUDIT</text><strong>系统审计与使用分析</strong><small>页面访问、主动操作与安全事件</small></view><view class="audit-mark">审</view></view>
    <view class="filters"><picker :range="hoursOptions" range-key="label" @change="changeHours"><view>{{ hoursLabel }}⌄</view></picker><picker :range="resultOptions" range-key="label" @change="changeResult"><view>{{ resultLabel }}⌄</view></picker><button @tap="load(1)">刷新</button></view>
    <view v-if="error" class="notice">{{ error }}</view>
    <view class="kpis"><view><text>行为记录</text><strong>{{ number(data.overview.request_count) }}</strong></view><view><text>活跃用户</text><strong>{{ number(data.overview.active_users) }}</strong></view><view><text>登录成功</text><strong>{{ number(data.overview.login_success) }}</strong></view><view><text>成功率</text><strong>{{ successRate }}%</strong></view></view>
    <view class="section-card"><view class="section-head"><view class="section-head-title">使用趋势</view><view class="section-head-meta">近 {{ filters.hours / 24 }} 天</view></view><scroll-view v-if="data.trends.length" scroll-x class="trend-scroll" :show-scrollbar="false"><view class="trend"><view v-for="item in data.trends" :key="item.day"><text>{{ compact(item.request_count) }}</text><i><em :style="{ height: trendHeight(item) }" /></i><small>{{ String(item.day || '').slice(5) }}</small></view></view></scroll-view><EmptyState v-else mark="势" title="暂无审计趋势" /></view>
    <view class="section-card"><view class="section-head"><view class="section-head-title">模块使用分布</view><view class="section-head-meta">{{ data.modules.length }} 个模块</view></view><view class="module-list"><view v-for="item in data.modules.slice(0,8)" :key="item.module"><view><strong>{{ moduleName(item.module) }}</strong><text>{{ number(item.active_users) }} 人 · {{ number(item.failure_count) }} 异常</text></view><view class="module-count">{{ number(item.request_count) }}</view><i><em :style="{ width: moduleWidth(item) }" /></i></view><EmptyState v-if="!data.modules.length" mark="模" title="暂无模块数据" /></view></view>
    <view class="section-card"><view class="section-head"><view class="section-head-title">审计明细</view><view class="section-head-meta">{{ number(data.total) }} 条</view></view><view class="audit-list"><view v-for="item in data.items" :key="item.id" class="audit-row"><view class="audit-top"><strong>{{ identity(item) }}</strong><StatusBadge :value="item.result" :text="resultName(item.result)" /></view><view class="audit-action">{{ moduleName(item.module) }} · {{ actionName(item.action) }}</view><view class="audit-path">{{ item.method }} {{ item.request_path }}</view><view class="audit-meta"><text>{{ time(item.occurred_at) }}</text><text>{{ item.duration_ms == null ? '--' : `${item.duration_ms} ms` }}</text></view></view><EmptyState v-if="!loading && !data.items.length" mark="审" title="暂无审计记录" /></view><view class="pager"><button :disabled="page <= 1 || loading" @tap="load(page - 1)">上一页</button><text>第 {{ page }} / {{ totalPages }} 页</text><button :disabled="page >= totalPages || loading" @tap="load(page + 1)">下一页</button></view></view>
  </view>
</template>

<script setup>
import { computed, reactive, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import EmptyState from '../../../components/netops/EmptyState.vue'
import StatusBadge from '../../../components/netops/StatusBadge.vue'
import { getSystemAudit } from '../../../api/netops'
import { messageLabel } from '../../../utils/labels'

const hoursOptions = [{ label: '近 24 小时', value: 24 }, { label: '近 7 天', value: 168 }, { label: '近 30 天', value: 720 }, { label: '近 90 天', value: 2160 }]
const resultOptions = [{ label: '全部结果', value: '' }, { label: '成功', value: 'success' }, { label: '拒绝', value: 'denied' }, { label: '失败', value: 'failed' }]
const filters = reactive({ hours: 168, result: '' }); const data = ref({ overview: {}, trends: [], modules: [], features: [], users: [], items: [], total: 0, page_size: 20 }); const page = ref(1); const loading = ref(false); const error = ref('')
const hoursLabel = computed(() => (hoursOptions.find((item) => item.value === filters.hours) || hoursOptions[1]).label); const resultLabel = computed(() => (resultOptions.find((item) => item.value === filters.result) || resultOptions[0]).label)
const maxTrend = computed(() => Math.max(1, ...data.value.trends.map((item) => Number(item.request_count || 0)))); const maxModule = computed(() => Math.max(1, ...data.value.modules.map((item) => Number(item.request_count || 0)))); const totalPages = computed(() => Math.max(1, Math.ceil(Number(data.value.total || 0) / Number(data.value.page_size || 20))))
const successRate = computed(() => { const total = Number(data.value.overview.request_count || 0); const failed = data.value.modules.reduce((sum, item) => sum + Number(item.failure_count || 0), 0); return total ? Math.max(0, ((1 - failed / total) * 100).toFixed(1)) : 100 })
onLoad(() => load(1))
async function load(next = 1) { loading.value = true; error.value = ''; page.value = next; try { data.value = await getSystemAudit({ ...filters, page: next, page_size: 20 }) } catch (err) { error.value = messageLabel(err.message) } finally { loading.value = false } }
function changeHours(event) { filters.hours = hoursOptions[Number(event.detail.value)].value; load(1) } function changeResult(event) { filters.result = resultOptions[Number(event.detail.value)].value; load(1) }
function number(value) { return Number(value || 0).toLocaleString() } function compact(value) { const n = Number(value || 0); return n >= 10000 ? `${(n / 10000).toFixed(1)}万` : String(n) }
function trendHeight(item) { return `${Math.max(5, Number(item.request_count || 0) / maxTrend.value * 100)}%` } function moduleWidth(item) { return `${Math.max(4, Number(item.request_count || 0) / maxModule.value * 100)}%` }
function moduleName(value) { return ({ auth: '登录认证', aiops: 'AIOps', collector: '采集监控', onu: 'ONU 管理', olt: 'OLT 管理', hfc: 'HFC 网络', boss: 'BOSS 数据', access: '账号组织', settings: '系统配置', system_audit: '系统审计', dashboard: '网络总览', platform: '平台服务' })[value] || value || '平台服务' }
function resultName(value) { return ({ success: '成功', denied: '拒绝', failed: '失败' })[value] || value || '--' } function actionName(value) { const raw = String(value || ''); return ({ login: '用户登录', change_password: '修改密码', search: '执行搜索', run_ai_analysis: '执行 AI 分析', ai_chat: 'AI 问答', export_quality_excel: '导出质差报表' })[raw] || raw.replace(/^get:/, '查看 · ').replace(/^post:/, '提交 · ').replaceAll('.', ' / ') }
function identity(item) { return item.display_name || item.username || (item.client_ip === '127.0.0.1' ? '系统探针' : '未认证访问') } function time(value) { if (!value) return '--'; const d = new Date(String(value)); return Number.isNaN(d.getTime()) ? String(value) : `${d.getMonth() + 1}-${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}` }
</script>

<style scoped>
.audit-page{padding-top:0}.audit-hero{display:flex;align-items:center;justify-content:space-between;margin:0 -24rpx 17rpx;padding:34rpx 30rpx;border-radius:0 0 28rpx 28rpx;background:linear-gradient(145deg,#142d4e,#285b91);color:#fff}.audit-hero text,.audit-hero strong,.audit-hero small{display:block}.audit-hero text{color:rgba(255,255,255,.52);font-size:17rpx;letter-spacing:2rpx}.audit-hero strong{margin-top:7rpx;font-size:31rpx}.audit-hero small{margin-top:7rpx;color:rgba(255,255,255,.68);font-size:19rpx}.audit-mark{display:flex;width:66rpx;height:66rpx;align-items:center;justify-content:center;border:1rpx solid rgba(255,255,255,.25);border-radius:21rpx;background:rgba(255,255,255,.1);font-size:25rpx}.filters{display:flex;gap:10rpx;margin-bottom:15rpx}.filters picker{min-width:0;flex:1}.filters picker view,.filters button{display:flex;height:62rpx;align-items:center;justify-content:center;border:1rpx solid #dfe5ec;border-radius:12rpx;background:#fff;color:#5e6c7f;font-size:19rpx}.filters button{width:88rpx;flex:none;background:#2865a6;color:#fff}.notice{margin-bottom:15rpx;padding:15rpx 18rpx;border-radius:12rpx;background:#fdebea;color:#b34540;font-size:21rpx}.kpis{display:grid;grid-template-columns:repeat(4,1fr);margin-bottom:17rpx;padding:16rpx 4rpx;border:1rpx solid #e1e7ee;border-radius:16rpx;background:#fff}.kpis view{text-align:center}.kpis text,.kpis strong{display:block}.kpis text{color:#8994a1;font-size:15rpx}.kpis strong{margin-top:4rpx;color:#285b91;font-size:24rpx}.trend-scroll{width:100%;white-space:nowrap}.trend{display:flex;width:max-content;min-width:100%;height:250rpx;align-items:flex-end;padding:20rpx 18rpx 13rpx}.trend>view{display:flex;width:70rpx;height:100%;flex:none;align-items:center;flex-direction:column}.trend text{height:29rpx;color:#657387;font-size:17rpx}.trend i{display:flex;width:25rpx;flex:1;align-items:flex-end;margin:6rpx 0;border-radius:7rpx;background:#edf2f6;overflow:hidden}.trend em{display:block;width:100%;border-radius:6rpx 6rpx 0 0;background:linear-gradient(#4e8bd0,#245c9b)}.trend small{color:#8b96a3;font-size:16rpx}.module-list{padding:0 22rpx 18rpx}.module-list>view{position:relative;display:grid;grid-template-columns:1fr auto;gap:8rpx;padding:17rpx 0}.module-list strong,.module-list text{display:block}.module-list strong{color:#344559;font-size:21rpx}.module-list text{margin-top:4rpx;color:#8b96a3;font-size:16rpx}.module-count{color:#2a639f;font-size:21rpx;font-weight:700}.module-list i{grid-column:1/3;height:7rpx;border-radius:99rpx;background:#edf1f5;overflow:hidden}.module-list em{display:block;height:100%;border-radius:99rpx;background:#4d87c7}.audit-list{padding:0 22rpx}.audit-row{padding:19rpx 0;border-bottom:1rpx solid #edf1f5}.audit-top{display:flex;align-items:center;justify-content:space-between}.audit-top strong{color:#2d3d50;font-size:22rpx}.audit-action{margin-top:8rpx;color:#526176;font-size:20rpx}.audit-path{margin-top:6rpx;overflow:hidden;color:#8792a0;font-family:monospace;font-size:16rpx;text-overflow:ellipsis;white-space:nowrap}.audit-meta{display:flex;justify-content:space-between;margin-top:8rpx;color:#9aa3ae;font-size:16rpx}.pager{display:flex;align-items:center;justify-content:space-between;padding:20rpx 22rpx}.pager button{display:flex;width:110rpx;height:54rpx;align-items:center;justify-content:center;border:1rpx solid #dbe3eb;border-radius:10rpx;background:#fff;color:#31679f;font-size:18rpx}.pager text{color:#808c9a;font-size:18rpx}
</style>
